private static HostPorts configuredHostPorts(
        Map<String, String> environment, int restPort, int hcpPort) throws IOException {
    String value = environment.get("JI_HOST_LOCATOR_FILE");
    if (value == null || value.isBlank()) return new HostPorts(restPort, hcpPort);
    java.nio.file.Path locator = java.nio.file.Path.of(value).toAbsolutePath().normalize();
    if (!java.nio.file.Files.exists(locator)) return new HostPorts(restPort, hcpPort);
    java.util.List<String> lines = java.nio.file.Files.readAllLines(locator);
    if (lines.size() != 2 || !lines.get(0).startsWith("rest=") || !lines.get(1).startsWith("hcp=")) {
        throw new IllegalStateException("invalid Host locator");
    }
    int persistedRest = strictPort(lines.get(0).substring(5));
    int persistedHcp = strictPort(lines.get(1).substring(4));
    if (persistedRest == persistedHcp) throw new IllegalStateException("invalid Host locator ports");
    return new HostPorts(persistedRest, persistedHcp);
}

private static void persistHostPorts(Map<String, String> environment, HostPorts ports) throws IOException {
    String value = environment.get("JI_HOST_LOCATOR_FILE");
    if (value == null || value.isBlank()) return;
    java.nio.file.Path locator = java.nio.file.Path.of(value).toAbsolutePath().normalize();
    java.nio.file.Path parent = locator.getParent();
    if (parent == null) throw new IllegalArgumentException("JI_HOST_LOCATOR_FILE requires a parent directory");
    java.nio.file.Files.createDirectories(parent);
    java.nio.file.Path temporary = java.nio.file.Files.createTempFile(parent, ".host-locator-", ".tmp");
    try {
        java.nio.file.Files.writeString(temporary,
                "rest=" + ports.rest() + "\nhcp=" + ports.hcp() + "\n",
                java.nio.charset.StandardCharsets.US_ASCII);
        try {
            java.nio.file.Files.move(temporary, locator,
                    java.nio.file.StandardCopyOption.ATOMIC_MOVE,
                    java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        } catch (java.nio.file.AtomicMoveNotSupportedException unsupported) {
            java.nio.file.Files.move(temporary, locator,
                    java.nio.file.StandardCopyOption.REPLACE_EXISTING);
        }
    } finally {
        java.nio.file.Files.deleteIfExists(temporary);
    }
}

private static int strictPort(String value) {
    try {
        int port = Integer.parseInt(value);
        if (port < 1 || port > 65_535) throw new NumberFormatException();
        return port;
    } catch (NumberFormatException failure) {
        throw new IllegalStateException("invalid Host locator port", failure);
    }
}

